"""Hand-written leads with gold facts. Each gold value was decided by reading the text against GUIDELINES.md and is
backed by `evidence`: exact substrings of the form or message that justify it (the dataset tests check they exist).

Gold fields: see GUIDELINES.md. Anything not stated in the lead is the neutral default (None / False / "unknown" / 0).
`ambiguous` lists fields where a reasonable reader could differ; those fields are not scored for that lead.
"""

DEFAULT_GOLD = dict(is_spam=False, primary_location=None, multiple_locations=False, property_type=None, budget_lakhs=None,
                    budget_range=None, timeline_months=None, has_reason=False, loan_status="unknown",
                    visit_or_call_requested=False, already_visited=False, ready_to_book=False, decision_maker="unknown",
                    n_questions=0, concrete_details_count=0)


def lead(id, category, lang, fmt, message, gold, evidence=None, form=None, ambiguous=(), notes="", name="Test Lead"):
    f = {"name": name, "phone": "", "location": "", "requirement": "", "budget": "", "timeline": "", "message": message}
    f.update(form or {})
    return {"id": id, "source": "handwritten", "category": category, "lang": lang, "format": fmt, "form": f,
            "gold": {**DEFAULT_GOLD, **gold}, "evidence": evidence or {}, "ambiguous_fields": list(ambiguous), "notes": notes}


